import csv
import io


_COLUMNS = (
    "id", "text", "language", "script", "source_type", "label", "source",
    "style", "group_id", "bt_similarity", "text_en", "orig_label",
    "split_hint", "annotator_agreement",
)


def _reader(lines, *, strict=False):
    return csv.reader(
        lines, delimiter=",", quotechar='"', doublequote=True, strict=strict
    )


def parse_csv(raw_csv: str):
    stream = io.StringIO(raw_csv.removeprefix("\ufeff"), newline="")
    header = None

    # The header occupies one physical line. Find it before parsing the body
    # so that stray quotes in a preamble cannot absorb the header or data.
    for line in stream:
        try:
            candidate = next(_reader([line], strict=True), [])
        except csv.Error:
            continue
        if tuple(value.strip().casefold() for value in candidate) == _COLUMNS:
            header = candidate
            break

    if header is None:
        stream.seek(0)
        records = _reader(stream)
        header = next((record for record in records if record), [])
    else:
        records = _reader(stream)

    width = len(header)
    if not width:
        return {"columns": [], "rows": []}

    normalized = [value.strip().casefold() for value in header]
    text_index = normalized.index("text") if "text" in normalized else width - 1
    rows = []
    for row in records:
        difference = len(row) - width
        if difference < 0:
            row.extend([""] * -difference)
        elif difference > 0:
            # Assume surplus separators are unquoted commas in the text field.
            end = text_index + difference + 1
            row[text_index:end] = [",".join(row[text_index:end])]
        rows.append(row)

    return {"columns": header, "rows": rows}
